(function(root){root.EdoStages={create({scene,shadows,obstacles,villageMeshes,villageLights}){const B=BABYLON,V=B.Vector3,C=B.Color3,cache={};const villageObstacles=obstacles.map(o=>({...o}));let active=null,time=0;
function material(name,color,shine=false){const m=new B.StandardMaterial(name,scene);m.diffuseColor=C.FromHexString(color);m.specularColor=shine?new C(.65,.75,.8):new C(.03,.03,.03);return m;}
const grass=material('meadow grass','#526a36'),sand=material('river sand','#b6a786'),mud=material('peat earth','#4c5540'),rockMat=material('river stone','#6b776e'),bark=material('weathered timber','#514332'),foliage=material('willow leaves','#415b39'),reeds=material('reed stems','#73794e'),water=material('moving river','#427f8a',true),bog=material('still bog','#354e44',true);water.alpha=.83;water.emissiveColor=new C(.025,.07,.08);bog.alpha=.88;
function mesh(n,opts,pos,mat,parent,solid=false){const m=B.MeshBuilder.CreateBox(n,opts,scene);m.position.set(...pos);m.material=mat;m.parent=parent;m.receiveShadows=true;m.metadata={worldSolid:solid};if(solid)shadows.addShadowCaster(m);return m;}
function ell(n,pos,scale,mat,parent,solid=false){const m=B.MeshBuilder.CreateSphere(n,{diameter:2,segments:10},scene);m.position.set(...pos);m.scaling.set(...scale);m.material=mat;m.parent=parent;m.receiveShadows=true;m.metadata={worldSolid:solid};if(solid)shadows.addShadowCaster(m);return m;}
function build(id){const node=new B.TransformNode('terrain '+id,scene),blocked=[],waves=[];let seed=id==='plains'?63:id==='marsh'?101:211;const rand=()=>{seed=seed*16807%2147483647;return(seed-1)/2147483646;};const floor=mesh('terrain ground',{width:170,height:.4,depth:170},[0,-.22,15],id==='plains'?grass:id==='marsh'?mud:sand,node,true);
function stone(x,z,r=1){ell('cover boulder',[x,r*.45,z],[r,r*.6,r*.8],rockMat,node,true);blocked.push({x,z,w:r*2+.65,d:r*1.6+.65});}
function tree(x,z,h,dead=false){const trunk=B.MeshBuilder.CreateCylinder('terrain trunk',{height:h,diameterTop:.08,diameterBottom:.35,tessellation:8},scene);trunk.position.set(x,h/2,z);trunk.parent=node;trunk.material=bark;trunk.metadata={worldSolid:true};for(let j=0;j<3;j++){let b=mesh('gnarled branch',{width:.12,height:h*.45,depth:.12},[x+(j-1)*.45,h*.7,z],bark,node,true);b.rotation.z=(j-1)*.6;}if(!dead){for(let i=0;i<3;i++)ell('leaf canopy',[x+(i-1)*1.1,h+i*.2,z],[2.2,1.4,1.8],foliage,node);} }
function tuft(x,z,h=.7){for(let k=0;k<3;k++){const t=B.MeshBuilder.CreateCylinder('reed',{height:h,diameterBottom:.065,diameterTop:.008,tessellation:3},scene);t.position.set(x+(k-1)*.09,h/2,z);t.parent=node;t.material=id==='plains'?grass:reeds;}}
for(let i=0;i<150;i++){const x=(rand()-.5)*85,z=rand()*95-27;if(Math.abs(x)<4)continue;tuft(x,z,.35+rand()*(id==='marsh'?1.6:.6));}
if(id==='plains'){for(let i=0;i<15;i++){const x=(i%2?-1:1)*(19+rand()*30),z=rand()*90-10;ell('rolling hill',[x,1,z],[9+rand()*8,3+rand()*4,10],grass,node);}for(const [x,z] of [[-10,0],[9,18],[-13,32],[14,-16]])stone(x,z,1.1);for(let i=0;i<9;i++)tree((i%2?-1:1)*(22+rand()*15),rand()*90-20,4+rand()*3);}
if(id==='marsh'){for(let i=0;i<12;i++){const x=(i%2?-1:1)*(6+rand()*14),z=rand()*65-15;ell('bog pool',[x,.015,z],[3+rand()*3,.025,2+rand()*4],bog,node);}for(let z=-23;z<44;z+=1.15)mesh('boardwalk plank',{width:4.6,height:.09,depth:1.03},[Math.sin(z*.04)*.2,.025,z],bark,node,true);for(let i=0;i<21;i++)tree((i%2?-1:1)*(9+rand()*22),rand()*80-20,3+rand()*4,true);stone(-8,7,.9);stone(10,28,1.1);}
if(id==='river'){const stream=B.MeshBuilder.CreateGround('river current',{width:160,height:13,subdivisions:28,updatable:true},scene);stream.position.set(0,.015,16);stream.material=water;stream.parent=node;waves.push(stream);for(let i=0;i<32;i++){let x=-55+i*3.5;ell('bank stone',[x,.12,9],[.6,.3,.5],rockMat,node);ell('bank stone',[x,.12,23],[.5,.28,.6],rockMat,node);}for(let z=8;z<=24;z+=.75)mesh('bridge deck',{width:5,height:.11,depth:.7},[0,.055,z],bark,node,true);for(const x of [-2.5,2.5]){mesh('bridge railing',{width:.1,height:.12,depth:16},[x,1.05,16],bark,node,true);for(let z=9;z<25;z+=3)mesh('bridge post',{width:.13,height:1.2,depth:.13},[x,.6,z],bark,node,true);}for(let i=0;i<14;i++)tree((i%2?-1:1)*(13+rand()*22),rand()*70-20,4+rand()*3);stone(-10,-3,1.1);stone(11,29,1);}
return cache[id]={node,blocked,waves};}
function village(){active=null;for(const item of Object.values(cache))item.node.setEnabled(false);villageMeshes.forEach(m=>m.setEnabled(true));villageLights.forEach(l=>l.setEnabled(true));obstacles.splice(0,obstacles.length,...villageObstacles);scene.fogDensity=.01;scene.fogColor=new C(.61,.61,.48);scene.clearColor=new B.Color4(.69,.61,.43,1);}
function apply(id){const stage=cache[id]??build(id);active=id;villageMeshes.forEach(m=>m.setEnabled(false));villageLights.forEach(l=>l.setEnabled(false));for(const [key,item] of Object.entries(cache))item.node.setEnabled(key===id);obstacles.splice(0,obstacles.length,...stage.blocked);scene.fogDensity=id==='marsh'?.022:id==='river'?.008:.006;scene.fogColor=id==='marsh'?new C(.37,.46,.4):id==='river'?new C(.58,.7,.72):new C(.7,.75,.61);scene.clearColor=id==='marsh'?new B.Color4(.42,.5,.43,1):id==='river'?new B.Color4(.64,.76,.8,1):new B.Color4(.73,.8,.71,1);}
function movementScale(x,z){if(active==='marsh'&&Math.abs(x)>3&&z>-15&&z<45)return .62;if(active==='river'&&z>9.5&&z<22.5&&Math.abs(x)>2.5)return .5;return 1;}
function tick(dt){time+=dt;for(const m of cache[active]?.waves??[]){const p=m.getVerticesData(B.VertexBuffer.PositionKind);for(let i=1;i<p.length;i+=3)p[i]=Math.sin(p[i-1]*.24+time*1.6+p[i+1]*.35)*.025;m.updateVerticesData(B.VertexBuffer.PositionKind,p);}}
return{apply,village,movementScale,tick,get active(){return active}};
}};})(window);
